import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

// Import Containers
import { DefaultLayoutComponent } from './containers';
import { AuthGuard } from './services/auth.guard';

import { P404Component } from './views/error/404.component';
import { P500Component } from './views/error/500.component';
import { LoginComponent } from './views/login/login.component';
import { RegisterComponent } from './views/register/register.component';

export const routes: Routes = [
  
  {
   /* path: 'dashboard',*/
   path :'',
    redirectTo: 'dashboard',
    pathMatch: 'full',
  },
  {
    path: '404',
    component: P404Component,
    data: {
      title: 'Page 404'
    }
  },
  {
    path: '500',
    component: P500Component,
    data: {
      title: 'Page 500'
    }
  },
  {
    path: 'login',
    component: LoginComponent,
    data: {
      title: 'Login Page'
    }
  },
  {
    path: 'register',
    component: RegisterComponent,
    data: {
      title: 'Register Page'
    },

  },
  {
    path: '',
    component: DefaultLayoutComponent,
    data: {
      title: 'Home'
    },canActivate:[AuthGuard],
    children: [
  
      {
        path: 'patients',
        loadChildren: () => import('./views/patient/patient.module').then(m => m.PatientModule)
      },
      {
        path: 'dossier',
        loadChildren: () => import('./views/dossier/dossier.module').then(m => m.DossiertModule)
      },
      {
        path: 'users',
        loadChildren: () => import('./views/users/users.module').then(m => m.UsersModule)
      },
      {
        path: 'profil',
        loadChildren: () => import('./views/profil/profil.module').then(m => m.ProfilModule)
      },
      {
        path: 'laboratory',
        loadChildren: () => import('./views/laboratory/laboratory.module').then(m => m.LaboratoryModule)
      },
      {
        path: 'leishmania-species',
        loadChildren: () => import('./views/leishmania-species/leishmania-species.module').then(m => m.LeishmaniaSpeciesModule)
      },
      {
        path: ' MolecularlTest',
        loadChildren: () => import('./views/molecularl-test/molecularl_test.module').then(m => m.MolecularlTestModule)
      },
      {
        path: 'disease',
        loadChildren: () => import('./views/disease/disease.module').then(m => m.DiseaseModule)
      },
      {
        path: 'charts',
        loadChildren: () => import('./views/chartjs/chartjs.module').then(m => m.ChartJSModule),canActivate:[AuthGuard]
      },
      {
        path: 'dashboard',
        loadChildren: () => import('./views/dashboard/dashboard.module').then(m => m.DashboardModule),canActivate:[AuthGuard]
      },
      {
        path: 'icons',
        loadChildren: () => import('./views/icons/icons.module').then(m => m.IconsModule)
      },
  
      
    ]
  },
  { path: '**', component: P404Component },
];
@NgModule({
  imports: [ RouterModule.forRoot(routes, { relativeLinkResolution: 'legacy' }) ],
  exports: [ RouterModule ]
})
export class AppRoutingModule {}
